import {
  OutputFormatter,
  RESULTS,
  catchError
} from "./packager-tool-79gws1zn.js";
import {
  __require
} from "./packager-tool-1yh8g550.js";

// src/services/bpmn-utils.ts
function entryPointFilePath(bpmnFileName, startEventId) {
  return `/content/${bpmnFileName}#${startEventId}`;
}
function extractEntryPointId(element) {
  const values = element.extensionElements?.values ?? [];
  for (const v of values) {
    if (v.$type === "uipath:entryPointId" && v.value) {
      return v.value;
    }
  }
  return;
}
async function parseBpmnXml(xml) {
  const { default: BpmnModdle } = await import("./index-xes9hekf.js");
  const moddle = new BpmnModdle;
  const parsed = await moddle.fromXML(xml);
  const root = parsed.rootElement;
  const processes = (root.rootElements ?? []).filter((element) => element.$type === "bpmn:Process");
  return { root, processes };
}
async function parseBpmnFile(fs, bpmnPath) {
  const absolutePath = fs.path.resolve(bpmnPath);
  if (!await fs.exists(absolutePath)) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: `File not found: ${absolutePath}`,
      Instructions: "Provide a valid path to a .bpmn file."
    });
    return null;
  }
  const xml = await fs.readFile(absolutePath, "utf-8");
  if (!xml) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: `Could not read file: ${absolutePath}`,
      Instructions: "Check file permissions."
    });
    return null;
  }
  const [parseError, parsed] = await catchError(parseBpmnXml(xml));
  if (parseError || !parsed) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: "BPMN parse failed",
      Instructions: (parseError ?? new Error("unknown parse error")).message
    });
    return null;
  }
  const { root, processes } = parsed;
  if (processes.length === 0) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: "No bpmn:Process element found",
      Instructions: "The BPMN file must contain at least one process."
    });
    return null;
  }
  return { xml, root, processes, absolutePath };
}

export { entryPointFilePath, extractEntryPointId, parseBpmnFile };

